agent-browser eval "
window.__testHistory = [];
const recordState = (event) => {
  const status = document.getElementById('status')?.innerText;
  const count = document.getElementById('count')?.innerText;
  const errors = document.getElementById('errors')?.innerText;
  const lis = Array.from(document.getElementById('events')?.getElementsByTagName('li') || []);
  const events = lis.map(li => ({
    idx: li.getAttribute('data-idx'),
    level: li.getAttribute('data-level'),
    text: li.innerText
  }));
  window.__testHistory.push({
    time: Date.now(),
    event,
    status,
    count,
    errors,
    eventsCount: lis.length,
    events
  });
};
recordState('init');
const observer = new MutationObserver((mutations) => {
  recordState('mutation');
});
observer.observe(document.body, {
  childList: true,
  subtree: true,
  characterData: true
});
'Observer installed';
"

